import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"WebSocket 连接排查","description":"灵萌私信/消息、管理端 H5、对外事件流 WebSocket 连不上的常见原因：Nginx 反代、CORS Origin 白名单（HTTP/HTTPS 不一致）、CDN 与票据认证。","frontmatter":{"title":"WebSocket 连接排查","description":"灵萌私信/消息、管理端 H5、对外事件流 WebSocket 连不上的常见原因：Nginx 反代、CORS Origin 白名单（HTTP/HTTPS 不一致）、CDN 与票据认证。"},"headers":[],"relativePath":"ops/websocket.md","filePath":"ops/websocket.md","lastUpdated":1787335593000}'),n={name:"ops/websocket.md"};function o(d,s,l,h,p,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="websocket-连接排查" tabindex="-1">WebSocket 连接排查 <a class="header-anchor" href="#websocket-连接排查" aria-label="Permalink to &quot;WebSocket 连接排查&quot;">​</a></h1><p>站内 <strong>私信/群聊</strong>、<strong>管理端 H5 实时能力</strong>、<strong>对外事件流（openstream）</strong> 均依赖 WebSocket。HTTP API 正常但「一直连接中 / 发不出消息 / WS 403」时，按本文从外到内排查。</p><h2 id="连接方式-先确认路径" tabindex="-1">连接方式（先确认路径） <a class="header-anchor" href="#连接方式-先确认路径" aria-label="Permalink to &quot;连接方式（先确认路径）&quot;">​</a></h2><p>灵萌 <strong>不</strong> 使用 <code>/api/message/ws</code> 作为升级地址，标准流程为：</p><ol><li><strong>换取票据</strong>（须登录）：<code>POST /api/message/ws/ticket</code>（或 <code>/api/v1/message/ws/ticket</code>，取决于 API 前缀）</li><li><strong>升级连接</strong>：<code>GET /ws?ticket=&lt;一次性票据&gt;</code>（根路径 <code>/ws</code>，<strong>不在</strong> <code>/api</code> 下）</li></ol><p>对外事件流类似：<code>POST /api/open/ws/ticket</code> → <code>GET /ws/open?ticket=...</code>。</p><p>H5 / 管理端在 HTTPS 页面下会自动使用 <code>wss://你的域名/ws?ticket=...</code>。</p><h2 id="现象与对应原因" tabindex="-1">现象与对应原因 <a class="header-anchor" href="#现象与对应原因" aria-label="Permalink to &quot;现象与对应原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>常见原因</th></tr></thead><tbody><tr><td>票据接口 502 / Connection refused</td><td>Go 进程未启动或反代 upstream 端口错误（默认 <code>127.0.0.1:8080</code>）</td></tr><tr><td><code>GET /ws</code> 返回 <strong>403</strong>，body 含「Origin 不在白名单内」</td><td><strong>CORS <code>allowed_origins</code> 未包含当前页面的 HTTPS Origin</strong>（见下文）</td></tr><tr><td><code>GET /ws</code> 返回 <strong>401</strong></td><td>票据无效或过期（属正常鉴权，说明 Origin 已通过）</td></tr><tr><td>仅 H5 失败、小程序正常</td><td>Nginx 未转发 <code>Upgrade</code> / <code>Connection</code> 头，或 CDN 未开 WebSocket</td></tr><tr><td>间歇性断开</td><td>CDN/负载均衡空闲超时过短；可加大 <code>proxy_read_timeout</code></td></tr></tbody></table><h2 id="_1-cors-白名单须与访问协议一致-高频" tabindex="-1">1. CORS 白名单须与访问协议一致（高频） <a class="header-anchor" href="#_1-cors-白名单须与访问协议一致-高频" aria-label="Permalink to &quot;1. CORS 白名单须与访问协议一致（高频）&quot;">​</a></h2><p>WebSocket 升级握手会带浏览器 <code>Origin</code> 头，后端与 HTTP CORS <strong>共用</strong> <code>config.yaml</code> 中的 <code>cors.allowed_origins</code> 白名单。</p><p>站点已启用 <strong>HTTPS</strong> 时，若白名单只写了 HTTP，连接会被拒绝：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 仅 HTTP：浏览器从 https://goqiang.b0518.top 打开时 Origin 为 https，不在名单内 → /ws 403</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_origins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://goqiang.b0518.top</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 同时列入 HTTPS（建议正式环境以 HTTPS 为准）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_origins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://goqiang.b0518.top</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://goqiang.b0518.top</span></span></code></pre></div><p>修改 <code>config.yaml</code> 后 <strong>须重启</strong> Go 进程后生效。</p><p><strong>自检（在服务器上）：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应返回 401（票据无效），而不是 403</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%{http_code}\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Origin: https://你的域名&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Connection: Upgrade&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Upgrade: websocket&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Sec-WebSocket-Version: 13&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;http://127.0.0.1:8080/ws?ticket=invalid&#39;</span></span></code></pre></div><ul><li><code>403</code> → 继续检查 <code>allowed_origins</code></li><li><code>401</code> → Origin 已通过，再查票据、Redis、进程是否在线</li></ul><p>初始化向导里填写的 <strong>CORS 白名单</strong> 同样须写完整协议（<code>https://</code>）。管理端、独立 H5 域名若与主站不同，需 <strong>每行一个 Origin</strong> 全部列入。</p><h2 id="_2-nginx-宝塔反代" tabindex="-1">2. Nginx / 宝塔反代 <a class="header-anchor" href="#_2-nginx-宝塔反代" aria-label="Permalink to &quot;2. Nginx / 宝塔反代&quot;">​</a></h2><p>站点 <code>location /</code> 反代到 Go 时，需支持协议升级（宝塔 Go 项目模板通常已包含）：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86400s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>/ws</code> 与 <code>/api</code> 走同一 <code>location /</code> 即可，<strong>无需</strong>单独再配 <code>/api/ws</code>。</p><h2 id="_3-cdn-edgeone-等" tabindex="-1">3. CDN（EdgeOne 等） <a class="header-anchor" href="#_3-cdn-edgeone-等" aria-label="Permalink to &quot;3. CDN（EdgeOne 等）&quot;">​</a></h2><p>域名接入 CDN 时，须在控制台 <strong>开启 WebSocket 转发</strong>。未开启时表现为外网连不上、源站直连正常。详见 <a href="/guide/quick-start">快速部署</a> 中的 CDN 提示。</p><h2 id="_4-服务与依赖" tabindex="-1">4. 服务与依赖 <a class="header-anchor" href="#_4-服务与依赖" aria-label="Permalink to &quot;4. 服务与依赖&quot;">​</a></h2><ul><li><strong>系统监控 → 系统状态</strong>：Redis、WebSocket 相关项应为正常</li><li><strong>系统监控 → 在线用户</strong>：有连接时能看到在线规模</li><li>Nginx <code>error.log</code> 若出现 <code>connect() failed (111: Connection refused) while connecting to upstream</code>，说明当时 Go 未监听 <code>8080</code>（部署/重启中或进程退出）</li></ul><h2 id="_5-日志快速对照" tabindex="-1">5. 日志快速对照 <a class="header-anchor" href="#_5-日志快速对照" aria-label="Permalink to &quot;5. 日志快速对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日志</th><th>含义</th></tr></thead><tbody><tr><td><code>POST .../message/ws/ticket</code> <strong>200</strong>，<code>GET /ws?ticket=...</code> <strong>403</strong></td><td>多为 <strong>Origin 白名单</strong> 问题</td></tr><tr><td><code>GET /ws</code> <strong>401</strong></td><td>票据问题或已消费；Origin 已通过</td></tr><tr><td>upstream <strong>502 / Connection refused</strong></td><td>Go 未运行或端口不对</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/features/message">私信与群聊</a></td><td>私信开关、区域配置</td></tr><tr><td><a href="/features/open-stream">对外事件流</a></td><td><code>/ws/open</code> 与 Pull/回调</td></tr><tr><td><a href="/guide/quick-start">快速部署</a></td><td>宝塔部署与 CDN WebSocket</td></tr><tr><td><a href="/guide/setup-wizard">初始化向导</a></td><td>CORS 白名单填写</td></tr><tr><td><a href="/ops/faq">常见问题</a></td><td>其他运维问题索引</td></tr></tbody></table>`,30)])])}const g=i(n,[["render",o]]);export{c as __pageData,g as default};
